/* 九条出身家庭往来：可选、可暂停，个人项目不能改变公产产权。 */
(()=>{'use strict';
const S=XTSandbox,W=XTWorld36,C=XTContent47,V=S.view,D=XTFamily56Data;
const old={scene:renderScene,newGame,restore,dispatch:S.dispatch,mapRooms:XTMap45.rooms,accepted:XTScene46.accepted};
const byId=Object.fromEntries(D.branches.map(b=>[b.id,b]));
const object=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state=()=>G?.family56||null,row=()=>state()?.rows?.[G?.world36?.playerId]||null;
let message='';
function legacy55(){return !!G&&G.origin==='寒门散修'&&G.variantIdx===0&&G.birthContext?.id==='daliang-qing';}
function branch(){return row()?byId[row().branchId]:D.branches.find(b=>b.origin===G?.origin&&b.variant===G?.variantIdx)||null;}
function house(){const d=G?.homes41;return d?.places?.find(h=>h.id===(row()?.houseId||d.residenceId))||null;}
function currentRegion(){return G?.currentRegion48?.id||G?.birthContext?.id;}
function birthRegion(){return row()?.regionId||G?.birthContext?.id;}
function local(){return currentRegion()===birthRegion();}
function homeHere(){const h=house();return !!h&&local()&&G.place===h.place&&['residence36','h41_inner'].includes(S.state().room)&&(h.residentIds.includes(G.world36.playerId)||h.chestOwners.includes(G.world36.playerId));}
function kin(){const ids=row()?.kinIds||Object.values(G?.world36?.people||{}).filter(n=>n.source==='开局家人档案'&&n.id.startsWith('family_'+G.world36.playerId+'_')).map(n=>n.id);return ids.map(id=>G.world36.people[id]).filter(Boolean);}
function kinPresent(){return kin().some(n=>XTCounty56.living(n.id)&&W.present(n.id));}
function kinState(){const people=kin();return people.some(n=>XTCounty56.living(n.id))?'alive':people.length?'memory':(G.family||[]).some(f=>f.alive===false)?'memory':'unknown';}
function writable(){if(!G.family56)G.family56={version:1,rows:{}};return G.family56;}
function record(q,text){q.journal.push({day:S.now(),text});q.journal=q.journal.slice(-32);addLog('家庭往来 · '+text,'mute');}
function rememberPresent(q){for(const n of kin().filter(n=>XTCounty56.living(n.id)&&W.present(n.id))){const r=W.relation(n.id);r.history.unshift({day:S.now(),text:'听你交代了「'+byId[q.branchId].title+'」：'+byId[q.branchId].choices[q.choice].effect});r.history=r.history.slice(0,24);const key='family56_'+q.branchId+'_'+q.choice;if(!r.deeds.includes(key))r.deeds.push(key);}}
function transact(fn){const ok=C.atomic(fn);if(!ok)message=C.takeFailure()||'本次家事未能保存，日期与材料已撤回。';render();return ok;}
function day(){const r=advanceDays(1,{act:'家庭往来',rate:0,incomeMul:0},{stopOnEvent:true});if(r.died){die('寿元耗尽');return false;}if(r.event){startEvent(r.event);return false;}return r.days===1;}
function followupReady(){const q=row();return q?.phase==='done'&&!q.returned&&(G.realm>q.realm||G.realm===q.realm&&G.layer>q.layer||S.now()>q.completedAt&&Object.values(G.county56?.regions?.[q.regionId]?.nodes||{}).some(n=>n.journal.some(h=>h.day>q.completedAt)));}
function reason(type){const b=branch(),q=row();if(!b||legacy55())return '青石药农沿用已有旧药路，其余家庭按各自档案参与。';if(type==='begin'){if(q)return '已有这段家庭记录，无须重演。';if(!G.world36?.startGranted)return '先安顿好这一生的住处。';if(!homeHere())return '回出生住处门厅或个人居室，再决定是否了解。';return '';}
 if(!q)return '尚未决定参与这段家庭往来。';if(['pause','resume'].includes(type))return '';if(q.paused)return '这段家事已搁置，可以随时继续。';if(type==='investigate'){if(q.phase!=='investigate')return '这段调查已经记过。';if(!local()||G.place!==b.investigation.place||S.state().room!=='f56_'+b.id)return '须沿真实路线到「'+b.investigation.title+'」所在处，不可远程完成。';return '';}
 if(['invest','independent','report','return'].includes(type)){if(!homeHere())return '这番生活安排留待回到出生住处办理。';if(type==='invest'||type==='independent'){if(q.phase!=='project')return '先了解实际情况，再作这回安排。';if(type==='invest'){if(!XTHome41.rights(house()).live)return '当前没有在此起居的资格，可保留独立生活笔记，不能强行存放工程。';if((G.inventory[b.project.item]||0)<b.project.amount)return '需要本人'+(BAG_ITEMS[b.project.item]?.name||b.project.item)+'一份；共有物不能拿来代用。';}return '';}
 if(type==='report')return q.phase==='report'?'':'这回尚无待交代的新安排。';if(type==='return')return followupReady()?'':'家人各有日常；待实际修行或地方往来有新变化，愿意时再回来。';}return '没有这项家事行动。';}
function dispatch(type){message='';if(type==='hide'){V.family56Hidden=true;render();return true;}if(!systemReady())return false;const why=reason(type);if(why){message=why;render();return false;}
 if(type==='pause'||type==='resume')return transact(()=>{row().paused=type==='pause';record(row(),type==='pause'?'暂且各忙各的，不因家事耽搁自己的修行与远行。':'又回到这段家庭往来，原先做过的事照旧保留。');});
 if(type==='begin')return transact(()=>{if(!day())return;const b=branch(),h=house(),people=kin();const q=writable().rows[G.world36.playerId]={branchId:b.id,ownerId:G.world36.playerId,houseId:h.id,regionId:G.birthContext.id,kinIds:people.map(n=>n.id),phase:'investigate',paused:false,choice:null,returned:false,journal:[]};record(q,b.opening);record(q,kinPresent()?'与现存家人核对各自处境，未替任何人答应新的生活。':kinState()==='alive'?'家人当前不在现场，只核对已有家书与自己的处境，未虚构一次当面交谈。':kinState()==='memory'?'只整理既有故人记录；不让已故的人再开口收物。':'亲缘资料仍待核定，只保留已有旧物，不凭空生成家人。');});
 if(type==='investigate')return transact(()=>{if(!day())return;const q=row();q.phase='project';q.investigatedAt=S.now();record(q,branch().investigation.text);});
 if(type==='invest'||type==='independent')return transact(()=>{if(!day())return;const why=reason(type);if(why){message=why;return;}const b=branch(),q=row();if(type==='invest')G.inventory[b.project.item]-=b.project.amount;q.choice=type;q.phase='report';q.project={title:b.project.title,item:type==='invest'?b.project.item:null,amount:type==='invest'?b.project.amount:0,effect:b.choices[type].effect};const h=house();h.projects56||={};h.projects56[q.ownerId]={...q.project,branchId:b.id,choice:type};record(q,b.choices[type].text);record(q,b.choices[type].effect);});
 if(type==='report')return transact(()=>{if(!day())return;const q=row();q.phase='done';q.realm=G.realm;q.layer=G.layer;q.completedAt=S.now();rememberPresent(q);record(q,kinPresent()?'把眼下的生活安排交代清楚。各人仍有自己的去留，不附加新的义务。':kinState()==='alive'?'把生活安排记成家书留在自己的物柜。家人不在现场，这不是一次当面交谈，也未替对方作决定。':kinState()==='memory'?'将自己的安排与故人旧事分开存记；没有把整理旧物写成一次团聚。':'留存自己的生活安排，亲人去向仍待核定，不推定生死。');});
 if(type==='return')return transact(()=>{if(!day())return;const q=row();q.returned=true;record(q,kinState()==='alive'&&!kinPresent()?'家人目前不在这里，只补记自己的近况，未虚构远程回应。':branch().followup[kinState()].replaceAll('{亲友}',kin().find(n=>XTCounty56.living(n.id)&&W.present(n.id))?.name||'家中人'));});
 return false;}
function button(label,type,off=false){return '<button type="button" class="sb-btn" data-family56="'+type+'" '+(off?'disabled':'')+'>'+esc(label)+'</button>';}
function panel(){const b=branch(),q=row();if(!b||legacy55()||!G.world36?.startGranted)return '';if(!q&&V.family56Hidden)return '';let text='',controls='';
 if(!q){text=b.opening;controls=button('了解这段往来 · 1日','begin',!!reason('begin'))+button('这次先不问','hide');}
 else if(q.paused){text='原来的记录保留。眼下可自由修炼、谋生、远行，愿意时再继续。';controls=button('继续这段往来','resume');}
 else if(q.phase==='investigate'){text='愿意进一步了解时，沿路线到「'+b.investigation.title+'」。这不影响其他修行与生计。';controls=button('实地核对 · 1日','investigate',!!reason('investigate'));}
 else if(q.phase==='project'){text=b.project.text;controls=button(b.choices.invest.label+' · 1日 / '+BAG_ITEMS[b.project.item].name+'×1','invest',!!reason('invest'))+button(b.choices.independent.label+' · 1日','independent',!!reason('independent'));}
 else if(q.phase==='report'){text=b.choices[q.choice].effect;controls=button(kinState()==='alive'?'回家交代各自安排 · 1日':'整理这回留下的记录 · 1日','report',!!reason('report'));}
 else{text=b.choices[q.choice].effect;controls=!q.returned?button('回访这段往来 · 1日','return',!!reason('return')):'';}
 const next=!q?'begin':q.phase==='investigate'?'investigate':q.phase==='project'?'independent':q.phase==='report'?'report':'return';return '<section class="life56-card family56-card"><small>'+esc(G.birthContext?.county||'出生县域')+' · '+esc(b.origin)+' · '+esc(G.variant||'家庭分支')+'</small><h3>'+esc(b.title)+'</h3><p>'+esc(text)+'</p><div class="life56-actions">'+controls+'</div>'+(!q?.paused&&reason(next)?'<p class="life56-muted">'+esc(reason(next))+'</p>':'')+(message?'<p class="life56-notice" role="status">'+esc(message)+'</p>':'')+(q&&!q.paused&&q.phase!=='done'?button('先去做其他事','pause'):'')+'<details><summary>归属与家庭记录</summary><p>'+esc(b.rights)+'</p><p>'+esc(b.kinNote)+'</p>'+((q?.journal||[]).map(h=>'<p>'+esc(h.text)+'</p>').join(''))+'</details></section>';}
function archives(){return Object.values(state()?.rows||{}).filter(r=>r.ownerId!==G.world36.playerId).map(q=>'<details class="life56-archive"><summary>上一代家事 · '+esc(byId[q.branchId]?.title)+'</summary><p>留存记录可读，不重演领取个人材料、钱款或产权。</p>'+q.journal.map(h=>'<p>'+esc(h.text)+'</p>').join('')+'</details>').join('');}
function accepted(){const b=branch(),q=row();if(!q||q.paused||q.phase==='done')return [];return [{title:'家庭往来：'+b.title+'（可选）',status:'留意中',text:{investigate:b.investigation.title,project:b.project.title,report:'回家交代各自安排'}[q.phase],where:q.phase==='investigate'?placeName(b.investigation.place)+' · '+b.investigation.title:placeName(house().place)+' · 出生住处',next:q.phase==='investigate'?'沿真实地图到专属调查地点，实地核对。':q.phase==='project'?'可投入本人材料，也可只保留独立生活安排。':'回住处核对这一回安排，不额外领奖。',need:'无强制期限，可搁置，不锁修炼、旅行、职业或公共支线。'}];}
function decorate(){if(!G||G.mode!=='idle')return;const b=branch(),h=house(),room=S.state().room,show=V.tab==='home'&&['','overview'].includes(V.sub||'')||V.tab==='scene'&&local()&&(G.place===h?.place&&['residence36','h41_inner'].includes(room)||b&&G.place===b.investigation.place&&room==='f56_'+b.id);if(!show)return;const scene=document.getElementById('scene'),scroll=scene?.querySelector('.sb-scroll');if(!scroll?.parentNode||scroll.querySelector('.family56-card,.life56-archive'))return;if(b&&room==='f56_'+b.id){const p=scene.querySelector('.next-hero-copy p');if(p)p.textContent=b.investigation.text;}const html=panel()+archives();if(!html)return;const node=document.createElement('div');node.innerHTML=html;(scroll.querySelector('.next-main')||scroll).append(node);node.querySelectorAll('[data-family56]').forEach(b=>b.onclick=()=>dispatch(b.dataset.family56));}
XTMap45.rooms=function(base){const rs=old.mapRooms(base),b=branch();return b&&!legacy55()&&local()&&G.place===b.investigation.place?[...rs,['f56_'+b.id,b.investigation.title]]:rs;};
S.dispatch=function(a,arg){if(a?.startsWith('f56:'))return dispatch(a.slice(4));return old.dispatch(a,arg);};
XTScene46.accepted=function(){return [...old.accepted(),...accepted()];};
renderScene=function(...a){const out=old.scene(...a);decorate();return out;};
newGame=function(...a){const carry=a.length>=4&&G?.mode==='dead'&&state()?JSON.parse(JSON.stringify(state())):null;V.family56Hidden=false;message='';const out=old.newGame(...a);if(carry)G.family56=carry;return out;};
restore=function(raw){try{const incoming=JSON.parse(raw),s=incoming.family56;if(s!=null){if(!object(s)||s.version!==1||!object(s.rows))throw Error('家庭记录无效');for(const [id,q]of Object.entries(s.rows)){if(!object(q)||q.ownerId!==id||!byId[q.branchId]||typeof q.houseId!=='string'||!XTCounty56Data.regions[q.regionId]||!Array.isArray(q.kinIds)||q.kinIds.some(x=>typeof x!=='string')||!['investigate','project','report','done'].includes(q.phase)||typeof q.paused!=='boolean'||typeof q.returned!=='boolean'||!Array.isArray(q.journal)||q.journal.length>32||q.journal.some(h=>!object(h)||!Number.isSafeInteger(h.day)||typeof h.text!=='string')||!incoming.homes41?.places?.some(h=>h.id===q.houseId)||['report','done'].includes(q.phase)&&!['invest','independent'].includes(q.choice)||q.phase==='done'&&(!Number.isSafeInteger(q.completedAt)||!Number.isInteger(q.realm)||!Number.isInteger(q.layer)))throw Error('家庭阶段或归属无效');}}for(const h of incoming.homes41?.places||[])if(h.projects56!=null&&!object(h.projects56))throw Error('个人项目容器无效');}catch(e){XTEconomy40.lastRestoreError='家庭长链记录无效，当前存档保留。';return false;}return old.restore(raw);};
window.XTFamily56={state,row,branch,house,legacy55,reason,dispatch,panel,accepted,followupReady};
window.XTLife56={inherit:(from,to)=>XTCounty56.inherit(from,to)};
})();
